fn solve(a: i8, b: i8) -> (i8, i8) {
    // Number of days pairing one of each until one type runs out
    let different = a.min(b);
    // Remaining items difference, integer-divide by 2 for same-type pairs
    let same = (a - b).abs() / 2;
    (different, same)
}

